const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
const fmt=d=>d?new Intl.DateTimeFormat('en-AU',{weekday:'short',day:'numeric',month:'short',hour:'numeric',minute:'2-digit',timeZone:'Australia/Melbourne'}).format(new Date(d)):'—';
const dateKey=d=>d?new Intl.DateTimeFormat('en-CA',{year:'numeric',month:'2-digit',day:'2-digit',timeZone:'Australia/Melbourne'}).format(new Date(d)):'—';
const ico=(n,c='nl-ico')=>window.NLIcon?window.NLIcon(n,c):'';
const state={session:null,bootstrap:null,view:'today',tasks:[],selected:null,wizard:null,taskScope:'active',overlayReturnFocus:null};
const labels={today:'Today',tasks:'Tasks',booking:'Booking',attention:'Needs attention',team:'Team',availability:'Availability',editor:'Editor queue',services:'Services & packages',roles:'Roles & access',integrations:'Integrations',settings:'Settings'};
const mobileLabels={today:'Today',tasks:'Tasks',booking:'Booking',attention:'Attention'};
const navIcons={today:'home',tasks:'tasks',booking:'calendar',attention:'alert',team:'team',availability:'clock',editor:'editor',services:'plus',roles:'shield',integrations:'link',settings:'settings'};
const serviceIcons={photos:'camera',floorplan:'floorplan',video:'video',drone:'drone',twilight:'twilight',reels:'social'};
const availabilityDays=Object.freeze([{key:'mon',label:'Monday',short:'Mon'},{key:'tue',label:'Tuesday',short:'Tue'},{key:'wed',label:'Wednesday',short:'Wed'},{key:'thu',label:'Thursday',short:'Thu'},{key:'fri',label:'Friday',short:'Fri'},{key:'sat',label:'Saturday',short:'Sat'},{key:'sun',label:'Sunday',short:'Sun'}]);
const availabilityZones=Object.freeze(['Australia/Melbourne','Australia/Sydney','Australia/Brisbane','Australia/Adelaide','Australia/Perth','Australia/Hobart','Australia/Darwin']);
const contracts=window.NorthlightContracts;
const signalRendered=()=>queueMicrotask(()=>document.dispatchEvent(new CustomEvent('northlight:rendered')));
function passwordSetupView(){const photographer=state.session?.role==='photographer';return '<div class="login credential-setup"><section class="login-art credential-art" aria-labelledby="credentialProductTitle"><div class="mark"><div class="logo" aria-hidden="true">N</div>Northlight</div><div class="login-copy"><div class="eyebrow">Protected account setup</div><h1 id="credentialProductTitle">Your access.<br>Your password.</h1><p>The temporary pilot credential ends here. Choose a personal password before any workspace data or action becomes available.</p></div><small>Northlight · REALCAPTURE</small></section><section class="login-form-wrap credential-form-wrap"><form class="login-card credential-card" id="requiredPasswordForm" aria-describedby="credentialIntro requiredPasswordError"><div class="mobile-wordmark"><div class="logo" aria-hidden="true">N</div><h1>Northlight · REALCAPTURE</h1></div><div class="setup-progress" aria-label="Account setup progress"><span class="is-current">1</span><i></i><span>2</span></div><div class="eyebrow">Step 1 · Account security</div><h2>Choose your personal password</h2><p id="credentialIntro">Signed in as <strong>'+esc(state.session?.email||'your Northlight account')+'</strong>. This required step cannot be skipped.</p><div class="field"><label for="requiredCurrentPassword">Current or temporary password</label><input id="requiredCurrentPassword" type="password" autocomplete="current-password" maxlength="128" required></div><div class="field"><label for="requiredNewPassword">New personal password</label><input id="requiredNewPassword" type="password" autocomplete="new-password" minlength="12" maxlength="128" aria-describedby="requiredPasswordHint" required><small class="field-help" id="requiredPasswordHint">Use 12–128 characters and do not reuse the temporary pilot password.</small></div><div class="field"><label for="requiredConfirmPassword">Confirm personal password</label><input id="requiredConfirmPassword" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></div><div id="requiredPasswordError" class="hint hidden" role="alert" aria-live="assertive" aria-atomic="true" tabindex="-1"></div><button class="btn primary block" type="submit">'+ico('lock')+'Set personal password</button>'+(photographer?'<div class="setup-next"><span>'+ico('calendar')+'</span><div><strong>Next: connect Google Calendar</strong><small>After signing in again, Calendar becomes your priority setup step so busy time protects every booking.</small></div></div>':'<div class="setup-next"><span>'+ico('check')+'</span><div><strong>Next: enter your workspace</strong><small>Sign in again with the personal password you just created.</small></div></div>')+'<button class="btn ghost block setup-signout" id="requiredSetupLogout" type="button">Sign out instead</button></form></section></div>'}
function bindRequiredPassword(){const form=$('#requiredPasswordForm'),current=$('#requiredCurrentPassword'),next=$('#requiredNewPassword'),confirmPassword=$('#requiredConfirmPassword'),box=$('#requiredPasswordError'),button=form?.querySelector('button[type="submit"]');$('#requiredSetupLogout').onclick=logout;form.onsubmit=async event=>{event.preventDefault();box.classList.add('hidden');[current,next,confirmPassword].forEach(input=>input.removeAttribute('aria-invalid'));const fail=(message,input)=>{box.textContent=message;box.classList.remove('hidden');input?.setAttribute('aria-invalid','true');(input||box).focus?.()};if(!current.value)return fail('Enter the current or temporary password.',current);if(next.value.length<12)return fail('Use at least 12 characters for the personal password.',next);if(next.value===current.value)return fail('Choose a personal password different from the current password.',next);if(next.value!==confirmPassword.value)return fail('The personal passwords do not match.',confirmPassword);button.disabled=true;button.setAttribute('aria-busy','true');try{const data=await api('/api/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword:current.value,newPassword:next.value})});state.session=null;state.bootstrap=null;state.tasks=[];state.selected=null;state.wizard=null;render();toast('Personal password saved',data.message||'Sign in again with your personal password.');setTimeout(()=>$('#email')?.focus(),0)}catch(failure){fail(failure.message||'Could not update password.');button.disabled=false;button.removeAttribute('aria-busy')}}}
async function api(path,opt={}){const r=await fetch(path,{credentials:'include',headers:{'content-type':'application/json',...(opt.headers||{})},...opt});let d={};try{d=await r.json()}catch{}if(!r.ok){const suffix=typeof d.detail==='string'&&d.detail.length<180?` · ${d.detail}`:'',e=new Error((d.error||`Request failed (${r.status})`)+suffix);e.status=r.status;e.code=d.code||d.detail?.code||null;e.detail=d.detail&&typeof d.detail==='object'?d.detail:{};e.data=d;throw e}return d}
function toast(title,msg=''){const t=$('#toast');if(!t)return;t.innerHTML=`<strong>${esc(title)}</strong>${msg?`<span>${esc(msg)}</span>`:''}`;t.classList.remove('hidden');clearTimeout(window.__nlToast);window.__nlToast=setTimeout(()=>t.classList.add('hidden'),3800)}
function initials(n='Northlight'){return String(n).split(/\s+/).filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase()||'N'}
function navFor(role){return contracts?.navFor(role)||['today','tasks']}
function person(id){return(state.bootstrap?.users||[]).find(x=>x.id===id)}
function serviceName(code){return(state.bootstrap?.services||[]).find(x=>x.code===code)?.name||String(code||'').replaceAll('_',' ')}
function statusBadge(s){const v=String(s||'assigned').replaceAll('_',' '),bad=['declined','cancelled','failed'].includes(s),warn=['assigned','revision','reschedule_requested','waiting'].includes(s);return`<span class="badge ${bad?'bad':warn?'warn':''}"><i class="dot"></i>${esc(v)}</span>`}
function greeting(){const h=Number(new Intl.DateTimeFormat('en-AU',{hour:'2-digit',hour12:false,timeZone:'Australia/Melbourne'}).format(new Date()));return h<12?'Good morning':h<18?'Good afternoon':'Good evening'}
function roleCanCreate(){return['admin','owner','agent'].includes(state.session?.role)}
function isManagement(){return contracts?.isManagement(state.session)||['admin','owner'].includes(state.session?.role)}
function visibleTasks(scope='active'){const alive=(state.tasks||[]).filter(t=>!t.deleted_at);if(scope==='archived'&&isManagement())return alive.filter(t=>!!t.archived_at);return alive.filter(t=>!t.archived_at)}
function currentTasks(){return visibleTasks('active').filter(t=>!['delivered','cancelled'].includes(t.status))}
function ensureValidView(){const allowed=navFor(state.session?.role);if(!allowed.includes(state.view)){state.view=allowed[0]||'today';state.taskScope='active'}return allowed}
function emptyCopy(context='tasks'){const role=state.session?.role;if(role==='photographer')return context==='today'?'No current shoots are assigned to you. New bookings will appear here.':'No visible shoots are assigned to you.';if(role==='editor')return context==='today'?'No current editing work is assigned to you. New jobs will appear here.':'No visible editing work is assigned to you.';return context==='today'?'No current work. Create a property task when you are ready.':'No visible tasks.'}
function proddyLink(){return`<a href="https://proddyg.com" target="_blank" rel="noopener noreferrer" aria-label="Visit ProddyG">${ico('spark')}<span>Crafted by <strong>ProddyG</strong></span></a>`}
function loginView(){return`<div class="login"><section class="login-art" aria-labelledby="loginProductTitle"><div class="mark"><div class="logo" aria-hidden="true">N</div>Northlight</div><div class="login-copy"><div class="eyebrow">REALCAPTURE · Property media operations</div><h1 id="loginProductTitle">One property.<br>One clear workflow.</h1><p>Book. Shoot. Edit. Deliver.<br><strong>Everyone knows what happens next.</strong></p></div><small>Melbourne · Australia</small></section><section class="login-form-wrap"><form class="login-card" id="loginForm" aria-describedby="loginIntro loginError"><div class="mobile-wordmark"><div class="logo" aria-hidden="true">N</div><h1>Northlight · REALCAPTURE</h1></div><div class="eyebrow">Secure workspace</div><h2>Sign in</h2><p id="loginIntro">Use the credentials provided by your administrator.</p><div class="field"><label for="email">Email</label><input id="email" type="email" autocomplete="username" required placeholder="you@company.com" aria-errormessage="loginError"></div><div class="field"><label for="password">Password</label><input id="password" type="password" autocomplete="current-password" required placeholder="••••••••••" aria-errormessage="loginError"></div><button class="btn primary block" type="submit">${ico('lock')}Sign in</button><div id="loginError" class="hint hidden" role="alert" aria-live="assertive" aria-atomic="true" tabindex="-1"></div><div class="crafted">${proddyLink()}</div></form></section></div>`}
function appFrame(){const n=ensureValidView(),mobile=contracts?.mobileNavFor(state.session.role)||{primary:n,more:[]},moreActive=mobile.more.includes(state.view);return`<div class="app"><aside class="sidebar"><div class="mark"><div class="logo" aria-hidden="true">N</div>Northlight</div><nav class="nav" aria-label="Primary navigation">${n.map(x=>`<button type="button" data-view="${x}" class="${state.view===x?'active':''}" ${state.view===x?'aria-current="page"':''}><span>${ico(navIcons[x])}</span>${labels[x]}</button>`).join('')}<div class="section">Quick action</div>${roleCanCreate()?`<button type="button" data-new-task><span>${ico('plus')}</span>New property task</button>`:''}</nav><div class="sidebar-user"><div class="avatar">${initials(state.session.name)}</div><div><strong>${esc(state.session.name)}</strong><span>${esc(state.session.roleLabel||state.session.role)}</span></div></div><div class="crafted sidebar-crafted">${proddyLink()}</div></aside><main class="main"><header class="topbar"><div><h2>${labels[state.view]||'Northlight'}</h2><small>REALCAPTURE · ${esc(state.session.name)}</small></div><div class="toolbar"><span class="role-pill">${esc(state.session.roleLabel||state.session.role)}</span><button class="btn secondary" id="logoutBtn" type="button">${ico('logout')}Sign out</button></div></header><section class="content" id="page" aria-labelledby="pageTitle"></section></main><nav class="mobile-nav" aria-label="Mobile navigation">${mobile.primary.map(x=>`<button type="button" data-view="${x}" class="${state.view===x?'active':''}" ${state.view===x?'aria-current="page"':''}>${ico(navIcons[x])}<span>${mobileLabels[x]||labels[x]}</span></button>`).join('')}${mobile.more.length?`<button type="button" data-mobile-more class="${moreActive?'active':''}" ${moreActive?'aria-current="page"':''} aria-haspopup="dialog">${ico('more')}<span>More</span></button>`:''}</nav></div>`}
function taskRow(t){const ph=person(t.photographer_user_id),stateMark=t.archived_at?'<span class="badge">Archived</span>':statusBadge(t.status),when=fmt(t.scheduled_start),services=(t.service_codes||[]).map(serviceName).join(' · ');return`<button class="row task-row" type="button" data-task="${t.id}"><div class="task-main"><strong>${esc(t.property_name)}</strong><small>${esc(t.address)} · ${esc(t.suburb)} · ${esc(t.task_no)}</small><span class="task-mobile-meta">${esc(when)} · ${esc(ph?.name||'Unassigned')}</span></div><div class="task-person"><strong>${esc(ph?.name||'Unassigned')}</strong><small>Photographer</small></div><div class="task-schedule"><strong>${esc(when)}</strong><small>${esc(services)}</small></div>${stateMark}</button>`}
function attentionItems(){const a=[];for(const t of visibleTasks('active')){if(t.status==='assigned')a.push([t,'Photographer confirmation',`${person(t.photographer_user_id)?.name||'Photographer'} has not confirmed yet.`]);if(t.status==='declined')a.push([t,'Photographer declined','Assign another suitable photographer.']);if(t.status==='reschedule_requested')a.push([t,'New time requested','Review the proposed appointment time.']);if(t.status==='review')a.push([t,'Review ready','Edited media is waiting for approval.']);if(t.status==='raw_received'&&!t.editor_user_id)a.push([t,'Editor required','Source media is ready but no editor is assigned.'])}return a}
function ownerTeamPulse(){const users=state.bootstrap?.users||[],cards=users.filter(x=>['agent','photographer','editor'].includes(x.role_code)).slice(0,8),activeTasks=visibleTasks('active');return`<div class="card owner-card"><div class="card-head"><h3>Team pulse</h3><button class="btn ghost" type="button" data-view="team">Full team view</button></div><div class="card-body team-board">${cards.map(u=>{const active=activeTasks.filter(t=>!['delivered','cancelled'].includes(t.status)&&[t.agent_user_id,t.photographer_user_id,t.editor_user_id].includes(u.id)).length;return`<button class="person person-button" type="button" data-person="${u.id}"><div class="person-top"><div class="avatar">${initials(u.name)}</div><div><h4>${esc(u.name)}</h4><p>${esc(u.role_code)} · ${active} active</p></div></div><div class="meter" aria-hidden="true"><i style="width:${Math.min(100,active*18+10)}%"></i></div></button>`}).join('')}</div></div>`}
function todayView(){const all=visibleTasks('active'),ts=currentTasks(),today=dateKey(new Date()),todayJobs=ts.filter(t=>dateKey(t.scheduled_start)===today),attention=attentionItems(),delivered=all.filter(t=>t.status==='delivered').length,owner=isManagement();return`<div class="hero"><div><div class="eyebrow">Operations at a glance</div><h1>${greeting()}, ${esc(state.session.name.split(' ')[0])}.</h1><p>Routine work stays quiet. Decisions, exceptions and hand-offs come to you.</p></div>${roleCanCreate()?`<button class="btn primary" type="button" data-new-task>${ico('plus')}New property task</button>`:''}</div><div class="grid kpis"><div class="card kpi"><span>Active tasks</span><strong>${ts.length}</strong></div><div class="card kpi"><span>Today</span><strong>${todayJobs.length}</strong></div><div class="card kpi"><span>Needs attention</span><strong>${attention.length}</strong></div><div class="card kpi"><span>Delivered</span><strong>${delivered}</strong></div></div><div class="columns"><div class="card"><div class="card-head"><h3>Current work</h3><button class="btn ghost" type="button" data-view="tasks">View all</button></div><div class="list">${ts.slice(0,6).map(taskRow).join('')||`<div class="empty">${esc(emptyCopy('today'))}</div>`}</div></div><div class="card"><div class="card-head"><h3>Needs attention</h3><span class="badge ${attention.length?'warn':''}">${attention.length}</span></div><div class="card-body attention">${attention.slice(0,5).map(([t,h,p])=>`<button class="attention-item" type="button" data-task="${t.id}"><strong>${esc(h)} · ${esc(t.property_name)}</strong><p>${esc(p)}</p></button>`).join('')||'<div class="empty">Nothing needs intervention.</div>'}</div></div></div>${owner?ownerTeamPulse()+`<div id="opsCard" class="card owner-card"><div class="card-head"><h3>${ico('route')}Live operations timeline</h3><span class="badge">Loading</span></div><div class="empty">Loading the operational audit stream…</div></div><div id="financeCard" class="card owner-card"><div class="card-head"><h3>${ico('invoice')}Finance snapshot</h3><span class="badge">Management</span></div><div class="empty">Loading finance visibility…</div></div>`:''}`}
function tasksView(){const ts=visibleTasks(state.taskScope),archivedCount=isManagement()?visibleTasks('archived').length:0;return`<div class="hero"><div><div class="eyebrow">One property · one record</div><h1>${state.taskScope==='archived'?'Archived tasks.':'Tasks.'}</h1><p>${state.taskScope==='archived'?'Completed records stay searchable without cluttering daily operations.':'Booking, files, editing, comments, issues and delivery remain attached to the same property.'}</p></div><div class="toolbar">${isManagement()?`<button class="btn ${state.taskScope==='active'?'primary':'secondary'}" type="button" data-task-scope="active" aria-pressed="${state.taskScope==='active'}">Active</button><button class="btn ${state.taskScope==='archived'?'primary':'secondary'}" type="button" data-task-scope="archived" aria-pressed="${state.taskScope==='archived'}">Archived${archivedCount?` · ${archivedCount}`:''}</button>`:''}${roleCanCreate()&&state.taskScope==='active'?`<button class="btn primary" type="button" data-new-task>${ico('plus')}New property task</button>`:''}</div></div><div class="card"><div class="list">${ts.map(taskRow).join('')||`<div class="empty">${state.taskScope==='archived'?'No archived tasks.':esc(emptyCopy('tasks'))}</div>`}</div></div>`}
function attentionView(){const a=attentionItems();return`<div class="hero"><div><div class="eyebrow">Exception-first operations</div><h1>Needs attention.</h1><p>Only work requiring a decision, recovery or review belongs here.</p></div></div><div class="card"><div class="card-body attention">${a.map(([t,h,p])=>`<button class="attention-item" type="button" data-task="${t.id}"><strong>${esc(h)} · ${esc(t.property_name)}</strong><p>${esc(p)}</p></button>`).join('')||'<div class="empty">Everything is moving normally.</div>'}</div></div>`}
function teamView(){const users=state.bootstrap?.users||[],activeTasks=visibleTasks('active');return`<div class="hero"><div><div class="eyebrow">Owner visibility</div><h1>Team.</h1><p>Understand workload, coverage and connected calendars without exposing controls people do not need.</p></div>${state.session.role==='admin'?`<button class="btn primary" type="button" id="addTeam">${ico('plus')}Add team member</button>`:''}</div><div class="team-board">${users.filter(x=>x.active!==false).map(u=>{const assigned=activeTasks.filter(t=>!['delivered','cancelled'].includes(t.status)&&[t.agent_user_id,t.photographer_user_id,t.editor_user_id].includes(u.id));return`<button class="card person person-button" type="button" data-person="${u.id}"><div class="person-top"><div class="avatar">${initials(u.name)}</div><div><h4>${esc(u.name)}</h4><p>${esc(u.role_code)} · ${esc(u.email)}</p></div></div><div class="meter" aria-hidden="true"><i style="width:${Math.min(100,assigned.length*17+8)}%"></i></div><p style="margin-top:12px">${assigned.length} active assignment${assigned.length===1?'':'s'} · View details →</p></button>`}).join('')}</div>`}
function nextBusinessDays(n=5){const out=[],d=new Date();while(out.length<n){d.setDate(d.getDate()+1);const day=new Intl.DateTimeFormat('en-AU',{weekday:'short',timeZone:'Australia/Melbourne'}).format(d);if(!['Sat','Sun'].includes(day))out.push(new Date(d))}return out}
function bookingView(){const days=nextBusinessDays(),active=visibleTasks('active').filter(t=>!['cancelled','delivered'].includes(t.status));return`<div class="hero"><div><div class="eyebrow">Scheduling intelligence</div><h1>Booking.</h1><p>Northlight checks service coverage, working hours and the selected photographer’s connected calendar before assignment.</p></div>${roleCanCreate()?`<button class="btn primary" type="button" data-new-task>${ico('calendar')}Book a property</button>`:''}</div><div class="schedule-days">${days.map(d=>{const k=dateKey(d),jobs=active.filter(t=>dateKey(t.scheduled_start)===k);return`<div class="card schedule-day"><div class="eyebrow">${new Intl.DateTimeFormat('en-AU',{weekday:'short',day:'numeric',month:'short',timeZone:'Australia/Melbourne'}).format(d)}</div>${jobs.length?jobs.map(t=>`<button type="button" data-task="${t.id}" class="schedule-job"><strong>${new Intl.DateTimeFormat('en-AU',{hour:'numeric',minute:'2-digit',timeZone:'Australia/Melbourne'}).format(new Date(t.scheduled_start))}</strong><span>${esc(t.property_name)}</span><small>${esc(person(t.photographer_user_id)?.name||'Unassigned')}</small></button>`).join(''):'<div class="schedule-empty">No Northlight bookings</div>'}</div>`}).join('')}</div><div class="hint" style="margin-top:18px">Calendar conflicts and working-hour rules are validated again when the booking is created.</div>`}
function availabilityExceptionRow(kind,value={},index=0){const isDayOff=kind==='day-off',date=typeof value==='string'?value:value?.date||'',hours=value?.hours||value?.working_hours||['09:00','17:00'];return`<div class="availability-exception" data-exception="${kind}"><div class="field compact-field"><label for="${kind}-date-${index}">${isDayOff?'Unavailable date':'Special date'}</label><input id="${kind}-date-${index}" type="date" data-exception-date value="${esc(date)}" required></div>${isDayOff?'':`<div class="availability-time-range"><div class="field compact-field"><label for="${kind}-start-${index}">From</label><input id="${kind}-start-${index}" type="time" data-exception-start value="${esc(hours[0]||'09:00')}" required></div><span aria-hidden="true">—</span><div class="field compact-field"><label for="${kind}-end-${index}">To</label><input id="${kind}-end-${index}" type="time" data-exception-end value="${esc(hours[1]||'17:00')}" required></div></div>`}<button class="btn secondary icon-btn exception-remove" type="button" data-remove-exception aria-label="Remove ${isDayOff?'day off':'special hours'}">${ico('close')}</button></div>`}
function availabilityWeek(p={}){const hours=p.working_hours||{};return availabilityDays.map(day=>{const range=Array.isArray(hours[day.key])?hours[day.key]:null;return`<div class="availability-day ${range?'is-working':'is-closed'}" data-availability-day="${day.key}"><div class="availability-day-name"><input id="work-${day.key}" type="checkbox" data-working-toggle ${range?'checked':''}><label for="work-${day.key}"><strong>${day.label}</strong><small>${range?'Working':'Unavailable'}</small></label></div><div class="availability-time-range"><div class="field compact-field"><label class="sr-only" for="work-${day.key}-start">${day.label} start</label><input id="work-${day.key}-start" type="time" data-working-start value="${esc(range?.[0]||'09:00')}" ${range?'':'disabled'} required></div><span aria-hidden="true">—</span><div class="field compact-field"><label class="sr-only" for="work-${day.key}-end">${day.label} end</label><input id="work-${day.key}-end" type="time" data-working-end value="${esc(range?.[1]||'17:00')}" ${range?'':'disabled'} required></div></div></div>`}).join('')}
function profileReady(p){return Boolean(p&&(p.areas||[]).length&&(p.service_codes||[]).length&&Object.keys(p.working_hours||{}).length)}
function readinessStep(key,title,copy,ready=false){return`<div class="readiness-step ${ready?'is-ready':'is-pending'}" data-readiness="${key}"><span class="readiness-mark">${ready?ico('check'):ico('clock')}</span><div><strong>${title}</strong><small>${copy}</small></div><span class="readiness-state">${ready?'Ready':'Pending'}</span></div>`}
function photographerAvailabilityView(p,u){if(!p)return`<div class="hero"><div><div class="eyebrow">Your availability</div><h1>Availability.</h1><p>Your Photographer profile has not been configured yet. Ask an Admin to add coverage and services before bookings can be offered.</p></div></div><div class="card section-card"><div class="empty">Photographer setup is required.</div></div>`;const timeZone=p.timezone||'Australia/Melbourne',zones=availabilityZones.includes(timeZone)?availabilityZones:[timeZone,...availabilityZones],daysOff=p.days_off||[],specialDays=(p.special_days||[]).filter(x=>x&&!x.closed),workingReady=Object.keys(p.working_hours||{}).length>0,coverageReady=(p.areas||[]).length>0&&(p.service_codes||[]).length>0,passwordReady=state.session?.mustChangePassword!==true;return`<div class="hero availability-hero"><div><div class="eyebrow">Photographer control centre</div><h1>Availability.</h1><p>Choose when Northlight may offer you work. Your private event details stay in Google; only busy time is used to protect bookings.</p></div><span class="badge info" id="availabilityGate">Checking booking readiness</span></div><div class="availability-shell"><div class="availability-primary"><section class="card readiness-card" aria-labelledby="readinessTitle"><div class="card-head"><div><div class="eyebrow">Booking readiness</div><h2 id="readinessTitle">Complete once. Stay protected.</h2></div><span class="readiness-score" id="readinessScore">—</span></div><div class="readiness-steps">${readinessStep('password','Personal password',passwordReady?'Your personal access is ready.':'Choose a personal password before setup continues.',passwordReady)}${readinessStep('calendar','Google Calendar','Connect your own Calendar so personal busy time blocks new work.',false)}${readinessStep('schedule','Weekly schedule',workingReady?'Regular working hours are configured.':'Keep at least one regular working day.',workingReady)}${readinessStep('coverage','Services & coverage',coverageReady?'Your service and area coverage is configured.':'An Admin must finish your service and area coverage.',coverageReady)}</div></section><form class="card availability-form" id="availabilityForm" data-version="${Number(p.availability_version||0)}" aria-labelledby="weeklyScheduleTitle"><div class="card-head"><div><div class="eyebrow">Regular availability</div><h2 id="weeklyScheduleTitle">Weekly schedule</h2></div><span class="badge">${esc(timeZone.replace('Australia/',''))} time</span></div><div class="availability-form-body"><fieldset class="availability-week"><legend class="sr-only">Regular working hours</legend>${availabilityWeek(p)}</fieldset><div class="availability-settings"><div class="field"><label for="availabilityTimezone">Time zone</label><select id="availabilityTimezone">${[...new Set(zones)].map(zone=>`<option value="${esc(zone)}" ${zone===timeZone?'selected':''}>${esc(zone.replace('_',' '))}</option>`).join('')}</select><small class="field-help">All availability and booking times are interpreted in this time zone. Existing bookings keep their original instant.</small></div></div><div class="availability-exceptions-grid"><section aria-labelledby="daysOffTitle"><div class="subsection-head"><div><h3 id="daysOffTitle">Days off</h3><p>Block a whole date without exposing why.</p></div><button class="btn secondary" type="button" id="addDayOff">${ico('plus')}Add day</button></div><div id="daysOffList" class="availability-exceptions">${daysOff.map((x,i)=>availabilityExceptionRow('day-off',x,i)).join('')||'<p class="availability-empty" data-empty-days>No days off added.</p>'}</div></section><section aria-labelledby="specialHoursTitle"><div class="subsection-head"><div><h3 id="specialHoursTitle">Special hours</h3><p>Override one date with different working hours.</p></div><button class="btn secondary" type="button" id="addSpecialHours">${ico('plus')}Add hours</button></div><div id="specialHoursList" class="availability-exceptions">${specialDays.map((x,i)=>availabilityExceptionRow('special-hours',x,i)).join('')||'<p class="availability-empty" data-empty-special>No special hours added.</p>'}</div></section></div></div><div class="availability-savebar"><div id="availabilitySaveStatus" role="status" aria-live="polite">Changes are checked again by Northlight before saving.</div><button class="btn primary" id="saveAvailability" type="submit">${ico('check')}Save availability</button></div></form></div><aside class="availability-aside"><section class="card calendar-connection" aria-labelledby="calendarConnectionTitle"><div class="provider-lockup"><span class="provider-icon">${ico('calendar')}</span><div><div class="eyebrow">Personal connection</div><h2 id="calendarConnectionTitle">Google Calendar</h2></div></div><div id="myCalStatus" class="connection-status" aria-live="polite"><span class="status-orb is-checking"></span><div><strong>Checking connection…</strong><small>Northlight is reading connection health.</small></div></div><div class="connection-actions"><button class="btn primary" id="connectMyCalendar" type="button">Connect / refresh</button><button class="btn secondary hidden" id="disconnectMyCalendar" type="button">Disconnect</button></div><p class="privacy-note">Northlight uses free/busy time for scheduling. Event titles, guests and descriptions are not shown in the portal.</p></section>${providerCard(p,u,true)}</aside></div>`}
function availabilityView(){const profiles=state.bootstrap?.providers||[],users=state.bootstrap?.users||[],own=state.session.role==='photographer';if(own){const p=profiles.find(x=>x.user_id===state.session.userId);return photographerAvailabilityView(p,person(p?.user_id))}const configured=profiles.filter(profileReady).length;return`<div class="hero"><div><div class="eyebrow">Photographer-controlled availability</div><h1>Availability.</h1><p>See who is ready for assignment. Photographers own their working hours and personal Calendar connection; management owns service and area coverage.</p></div><span class="badge info">${configured} of ${profiles.length} profiles configured</span></div><div id="calendarCoverage" class="grid provider-grid">${profiles.map(p=>providerCard(p,users.find(x=>x.id===p.user_id),false)).join('')}</div>`}
function providerCard(p,u,own){if(!p)return'<div class="card section-card"><div class="empty">No photographer profile configured.</div></div>';const days=availabilityDays.filter(day=>Array.isArray(p.working_hours?.[day.key])),services=(p.service_codes||[]).map(serviceName),areas=p.areas||[],body=`<div class="person-top"><div class="avatar">${initials(u?.name)}</div><div><h3>${esc(u?.name||'Photographer')}</h3><p>${esc(areas.join(' · ')||'Coverage not configured')}</p></div></div><div class="provider-facts"><div><span>Regular week</span><strong>${days.length?days.map(x=>x.short).join(' · '):'Not configured'}</strong></div><div><span>Services</span><strong>${esc(services.join(' · ')||'Not configured')}</strong></div><div><span>Travel protection</span><strong>${Number(p.travel_buffer_min||0)} min · ${Number(p.service_radius_km||25)} km radius</strong></div></div><div class="calendar-chip" data-calendar-user="${p.user_id}">Calendar status loading…</div>`;if(own)return`<section class="card provider-summary" aria-labelledby="providerSummaryTitle"><div class="card-head"><div><div class="eyebrow">Assignment profile</div><h2 id="providerSummaryTitle">Coverage & services</h2></div><span class="badge">Admin managed</span></div><div class="provider-summary-body">${body}<p class="privacy-note">Ask an Admin to change your service skills, coverage area, travel buffer or radius.</p></div></section>`;return`<article class="card provider-overview">${body}<button class="btn ghost provider-open" type="button" data-person="${p.user_id}">View Photographer profile ${ico('chevron')}</button></article>`}
function editorView(){const ts=visibleTasks('active').filter(t=>['raw_received','editing','revision'].includes(t.status));return`<div class="hero"><div><div class="eyebrow">Post-production queue</div><h1>Editor queue.</h1><p>Source media, active work and revisions stay attached to the property record.</p></div></div><div class="card"><div class="list">${ts.map(taskRow).join('')||'<div class="empty">No editing jobs in queue.</div>'}</div></div>`}
function servicesView(){const sv=state.bootstrap?.services||[],pk=state.bootstrap?.packages||[];return`<div class="hero"><div><div class="eyebrow">Booking catalogue</div><h1>Services & packages.</h1><p>Duration and buffers drive real booking calculations; packages keep repeat orders fast.</p></div></div><div class="columns"><div class="card"><div class="card-head"><h3>Services</h3></div><div class="service-admin-grid">${sv.map(x=>`<div class="service-admin"><span class="service-icon">${ico(serviceIcons[x.code]||'spark')}</span><div><strong>${esc(x.name)}</strong><small>${x.duration_min} min · ${x.buffer_before_min+x.buffer_after_min} min buffer</small></div><span class="badge">Active</span></div>`).join('')}</div></div><div class="card"><div class="card-head"><h3>Saved packages</h3></div><div class="card-body">${pk.map(x=>`<div class="attention-item"><strong>${esc(x.name)}</strong><p>${(x.service_codes||[]).map(serviceName).join(' · ')}</p></div>`).join('')||'<div class="empty">No saved packages.</div>'}</div></div></div>`}
function rolesView(){const roles=state.bootstrap?.roles||[];return`<div class="hero"><div><div class="eyebrow">Role-based control</div><h1>Roles & access.</h1><p>Permissions are enforced at the API and file-link level—not simply hidden in the interface.</p></div></div><div class="grid role-grid">${roles.map(r=>`<div class="card section-card"><span class="service-icon">${ico('shield')}</span><span class="badge">${esc(r.code)}</span><h3>${esc(r.name)}</h3><p class="detail-copy">${(r.permissions||[]).map(esc).join(' · ')||'Configured permissions'}</p></div>`).join('')}</div>`}
function recipientCard(mode='settings'){const cardClass=mode==='integration'?'card integration':'card section-card';return`<div class="${cardClass}" id="operationsRecipientCard"><span class="service-icon">${ico('mail')}</span><h3>Notification recipient</h3><p class="detail-copy">Assignment notices go to a real team email when available. This is the operational fallback for pilot accounts and task alerts.</p><div class="field"><label for="operationsEmail">Operations email</label><input id="operationsEmail" type="email" autocomplete="email" placeholder="operations@example.com" aria-describedby="operationsEmailStatus" disabled></div><button class="btn primary" type="button" id="saveOperationsEmail" disabled>Save recipient</button><div class="hint" id="operationsEmailStatus" role="status" aria-live="polite">Loading the saved recipient…</div></div>`}
function integrationCard(p,title,icon,desc,flow,get){const x=get(p),connected=x.status==='connected',disabled=p==='whatsapp'||x.status==='disabled',fresh=x.last_verified_at||x.updated_at,status=disabled?'Disabled':connected?'Connected':'Connection required',actions=disabled?'<button class="btn secondary" type="button" disabled>Disabled</button>':`<button class="btn primary" type="button" ${p==='xero'?'id="xeroConnect" ':''}data-connect="${p}">${connected?'Reconnect':'Connect'} ${title}</button><button class="btn secondary" type="button" data-test="${p}">Verify</button>${connected?`<button class="btn ghost integration-disconnect" type="button" data-disconnect="${p}">Disconnect</button>`:''}`;return`<article class="card integration provider-${p}"><div class="integration-title"><span class="provider-icon" aria-hidden="true">${ico(icon)}</span><div><h3>${title}</h3><small>${esc(x.account_label||'Not linked')}</small></div><span class="badge status ${!connected?'warn':''}">${status}</span></div><p>${desc}</p>${flow?`<div class="integration-flow" aria-label="${esc(title)} data flow"><div><span>Northlight → ${title}</span><strong>${esc(flow.outbound)}</strong></div><div><span>${title} → Northlight</span><strong>${esc(flow.inbound)}</strong></div></div>`:''}<div class="integration-health"><span class="status-orb ${connected?'is-healthy':disabled?'':'is-blocked'}"></span><span>${connected?(fresh?`Last verified ${esc(fmt(fresh))}`:'Connected · verification time pending'):disabled?'Intentionally unavailable for this release':'Connect before this workflow can run'}</span></div><div class="integration-actions">${actions}</div></article>`}
function integrationsView(){const s=state.bootstrap?.integrations||[],get=p=>s.find(x=>x.provider===p)||{},flows={dropbox:{outbound:'Upload and stage role-safe media',inbound:'Index file, rename and deletion changes'},google:{outbound:'Create and send operational email',inbound:'Verify draft and send state before retry'},xero:{outbound:'Create managed draft invoices',inbound:'Refresh invoice and payment status'}};return`<div class="hero"><div><div class="eyebrow">Connected services</div><h1>Integrations.</h1><p>One operational view, with each specialist service remaining its system of record. Every supported direction is explicit below.</p></div></div><div class="integration-grid">${integrationCard('dropbox','Dropbox','files','Private RAW, edited and final media with role-safe temporary access.',flows.dropbox,get)}${integrationCard('google','Google Workspace','mail','Shared operational email. Photographer-owned Calendar connections stay in Availability.',flows.google,get)}${integrationCard('xero','Xero','invoice','Optional accounting connection with management-only financial visibility.',flows.xero,get)}${integrationCard('whatsapp','WhatsApp','message','Optional channel intentionally disabled for the current REALCAPTURE pilot. Email is active.',null,get)}${state.session.role==='owner'?recipientCard('integration'):''}</div><div id="integrationPreflight" class="hint" role="status" aria-live="polite">Checking workspace readiness…</div>`}
function settingsView(){return`<div class="hero"><div><div class="eyebrow">Workspace configuration</div><h1>Settings.</h1><p>Northlight is configured for REALCAPTURE and Australia/Melbourne.</p></div></div><div class="grid settings-grid"><div class="card section-card"><span class="service-icon">${ico('shield')}</span><h3>Workspace</h3><p class="detail-copy">Northlight · REALCAPTURE<br>Melbourne time<br>Data hosted in Sydney</p></div><div class="card section-card"><span class="service-icon">${ico('mail')}</span><h3>Communication</h3><p class="detail-copy">Operational email enabled<br>WhatsApp disabled for this pilot<br>Task comments remain the source of truth</p></div><div class="card section-card"><span class="service-icon">${ico('files')}</span><h3>Media</h3><p class="detail-copy">Dropbox media storage connected<br>Role-checked temporary links<br>RAW media stays in Dropbox</p></div>${recipientCard('settings')}</div>`}
function renderPage(){ensureValidView();const p=$('#page');if(!p)return;const map={today:todayView,tasks:tasksView,booking:bookingView,attention:attentionView,team:teamView,availability:availabilityView,editor:editorView,services:servicesView,roles:rolesView,integrations:integrationsView,settings:settingsView};p.innerHTML=(map[state.view]||todayView)();const heading=p.querySelector('h1');if(heading){heading.id='pageTitle';heading.tabIndex=-1}bindDynamic();hydratePage();signalRendered()}
function render(){const root=$('#root');if(!state.session){root.innerHTML=loginView();bindLogin();return}if(state.session.mustChangePassword===true){root.innerHTML=passwordSetupView();bindRequiredPassword();signalRendered();return}ensureValidView();root.innerHTML=appFrame();renderPage();$('#logoutBtn').onclick=logout;syncNavigation()}
function navigate(view,{focus=true}={}){if(!navFor(state.session?.role).includes(view))view='today';state.view=view;if(state.view!=='tasks')state.taskScope='active';render();if(focus)requestAnimationFrame(()=>$('#page h1')?.focus())}
function readinessState(key,ready,copy=''){const row=$(`[data-readiness="${key}"]`);if(!row)return;row.classList.toggle('is-ready',Boolean(ready));row.classList.toggle('is-pending',!ready);const mark=$('.readiness-mark',row),stateLabel=$('.readiness-state',row),detail=$('small',row);if(mark)mark.innerHTML=ready?ico('check'):ico('clock');if(stateLabel)stateLabel.textContent=ready?'Ready':'Pending';if(copy&&detail)detail.textContent=copy;const all=$$('.readiness-step'),readyCount=all.filter(x=>x.classList.contains('is-ready')).length,score=$('#readinessScore');if(score)score.textContent=`${readyCount} / ${all.length}`}
function bindAvailabilityExceptions(){$$('[data-remove-exception]').forEach(button=>button.onclick=()=>{const row=button.closest('[data-exception]'),list=row?.parent;if(!row||!list)return;row.remove();if(!list.querySelector('[data-exception]'))list.innerHTML=`<p class="availability-empty" data-empty-${list.id==='daysOffList'?'days':'special'}>No ${list.id==='daysOffList'?'days off':'special hours'} added.</p>`})}
function addAvailabilityException(kind){const dayOff=kind==='day-off',list=$(dayOff?'#daysOffList':'#specialHoursList');if(!list)return;$('.availability-empty',list)?.remove();list.insertAdjacentHTML('beforeend',availabilityExceptionRow(kind,dayOff?'':{hours:['09:00','17:00']},`${Date.now()}-${list.children.length}`));bindAvailabilityExceptions();$('[data-exception]:last-child input',list)?.focus()}
function bindAvailabilityControls(){const form=$('#availabilityForm');if(!form)return;$$('[data-working-toggle]',form).forEach(toggle=>{toggle.onchange=()=>{const row=toggle.closest('[data-availability-day]'),inputs=$$('input[type="time"]',row),enabled=Boolean(toggle.checked);row?.classList.toggle('is-working',enabled);row?.classList.toggle('is-closed',!enabled);inputs.forEach(input=>input.disabled=!enabled);const label=$('.availability-day-name small',row);if(label)label.textContent=enabled?'Working':'Unavailable';readinessState('schedule',$$('[data-working-toggle]',form).some(x=>Boolean(x.checked)))} });if($('#addDayOff'))$('#addDayOff').onclick=()=>addAvailabilityException('day-off');if($('#addSpecialHours'))$('#addSpecialHours').onclick=()=>addAvailabilityException('special-hours');bindAvailabilityExceptions();form.onsubmit=saveAvailability}
function availabilityPayload(){const form=$('#availabilityForm'),workingHours={};for(const row of $$('[data-availability-day]',form)){const toggle=$('[data-working-toggle]',row),enabled=typeof toggle?.checked==='boolean'?toggle.checked:toggle?.getAttribute('checked')!==null;if(!enabled)continue;workingHours[row.dataset.availabilityDay]=[$('[data-working-start]',row)?.value,$('[data-working-end]',row)?.value]}const daysOff=$$('[data-exception="day-off"] [data-exception-date]',form).map(x=>x.value).filter(Boolean),specialDays=$$('[data-exception="special-hours"]',form).map(row=>({date:$('[data-exception-date]',row)?.value,hours:[$('[data-exception-start]',row)?.value,$('[data-exception-end]',row)?.value]})).filter(x=>x.date);return{expectedVersion:Number(form?.dataset.version||0),workingHours,daysOff,specialDays,timeZone:$('#availabilityTimezone')?.value||'Australia/Melbourne'}}
async function saveAvailability(event){event?.preventDefault?.();const form=$('#availabilityForm'),button=$('#saveAvailability'),status=$('#availabilitySaveStatus');if(!form||!button)return;if(form.reportValidity&&!form.reportValidity())return;button.disabled=true;button.setAttribute('aria-busy','true');status.textContent='Validating and saving your availability…';try{const payload=availabilityPayload(),d=await api('/api/availability',{method:'PATCH',body:JSON.stringify(payload)}),profile=d.profile||{...payload,working_hours:payload.workingHours,days_off:payload.daysOff,special_days:payload.specialDays,timezone:payload.timeZone,availability_version:Number(payload.expectedVersion)+1},profiles=state.bootstrap?.providers||[],index=profiles.findIndex(x=>x.user_id===state.session.userId);if(index>=0)profiles[index]={...profiles[index],...profile};toast('Availability saved','New booking checks now use this schedule.');renderPage()}catch(e){status.textContent=e.status===409?'Your availability changed elsewhere. Reload before saving again.':e.message;toast('Could not save availability',status.textContent)}finally{button.disabled=false;button.removeAttribute('aria-busy')}}
async function disconnectMyCalendar(){if(!confirm('Disconnect Google Calendar? New bookings will be paused until you reconnect. Existing Northlight bookings stay protected.'))return;const button=$('#disconnectMyCalendar');if(button){button.disabled=true;button.setAttribute('aria-busy','true')}try{const d=await api('/api/calendar/disconnect',{method:'POST'});toast('Calendar disconnected',d.message||'New assignment eligibility is paused.');renderPage()}catch(e){toast('Could not disconnect Calendar',e.message);if(button){button.disabled=false;button.removeAttribute('aria-busy')}}}
function bindDynamic(){$$('[data-task]').forEach(b=>b.onclick=()=>{state.overlayReturnFocus=b;openTask(b.dataset.task)});$$('[data-person]').forEach(b=>b.onclick=()=>{state.overlayReturnFocus=b;openPerson(b.dataset.person)});$$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$$('[data-task-scope]').forEach(b=>b.onclick=()=>{state.taskScope=b.dataset.taskScope;renderPage()});$$('[data-new-task]').forEach(b=>b.onclick=()=>{state.overlayReturnFocus=b;openWizard()});$$('[data-connect]').forEach(b=>b.onclick=()=>connect(b.dataset.connect));$$('[data-test]').forEach(b=>b.onclick=()=>testIntegration(b.dataset.test));$$('[data-disconnect]').forEach(b=>b.onclick=()=>disconnectIntegration(b.dataset.disconnect));if($('[data-mobile-more]'))$('[data-mobile-more]').onclick=e=>{state.overlayReturnFocus=e.currentTarget;openMobileNav()};if($('#addTeam'))$('#addTeam').onclick=e=>{state.overlayReturnFocus=e.currentTarget;openAddTeam()};if($('#connectMyCalendar'))$('#connectMyCalendar').onclick=()=>location.href=`/api/calendar/connect?return_to=${encodeURIComponent('/?view=availability')}`;if($('#disconnectMyCalendar'))$('#disconnectMyCalendar').onclick=disconnectMyCalendar;if($('#availabilityForm'))bindAvailabilityControls();if($('#saveOperationsEmail'))$('#saveOperationsEmail').onclick=saveOperationsRecipient}
async function hydratePage(){if(state.view==='today'&&isManagement())hydrateOwnerToday();if(state.view==='availability')hydrateCalendars();if(state.view==='integrations')hydrateIntegrations();if($('#operationsRecipientCard'))hydrateOperationsRecipient()}
function syncNavigation(){const active=$('.mobile-nav [aria-current="page"]');if(active&&!active.dataset.scrolled){active.dataset.scrolled='1';requestAnimationFrame(()=>active.scrollIntoView?.({block:'nearest',inline:'center',behavior:'smooth'}))}}
function openMobileNav(){const more=contracts?.mobileNavFor(state.session.role)?.more||[];if(!more.length)return;$('#overlay').innerHTML=`<div class="modal-bg mobile-more-bg" id="mobileMoreBg"><div class="modal mobile-more-modal" role="dialog" aria-modal="true" aria-labelledby="mobileMoreTitle" tabindex="-1"><div class="modal-head"><div><div class="eyebrow">Workspace navigation</div><h2 id="mobileMoreTitle">More</h2></div><button class="btn secondary icon-btn" type="button" id="closeMobileMore" aria-label="Close navigation">${ico('close')}</button></div><div class="modal-body"><nav class="more-nav" aria-label="More workspace destinations">${more.map(x=>`<button class="more-nav-item ${state.view===x?'active':''}" type="button" data-more-view="${x}" ${state.view===x?'aria-current="page"':''}><span>${ico(navIcons[x])}</span><strong>${labels[x]}</strong>${ico('chevron')}</button>`).join('')}</nav></div></div></div>`;$('#closeMobileMore').onclick=closeOverlay;$('#mobileMoreBg').onclick=e=>{if(e.target.id==='mobileMoreBg')closeOverlay()};$$('[data-more-view]').forEach(b=>b.onclick=()=>{const view=b.dataset.moreView;closeOverlay();navigate(view)})}
async function hydrateOperationsRecipient(){const card=$('#operationsRecipientCard'),input=$('#operationsEmail'),status=$('#operationsEmailStatus'),button=$('#saveOperationsEmail');if(!card||card.dataset.loaded)return;card.dataset.loaded='loading';card.setAttribute('aria-busy','true');try{const d=await api('/api/settings');input.value=d.operationsEmail||'';input.disabled=false;button.disabled=false;status.textContent=d.source==='workspace'?'Saved in Northlight.':'Using the deployment fallback. Save here to manage it in Northlight.';card.dataset.loaded='true'}catch(e){status.textContent=e.message;card.dataset.loaded='error'}finally{card.removeAttribute('aria-busy')}}
