function connect(p){location.href=`/api/oauth/${p}/start?return_to=${encodeURIComponent('/?view=integrations')}`}
async function disconnectIntegration(provider){const label={google:'Google Workspace',dropbox:'Dropbox',xero:'Xero'}[provider]||'integration';if(!confirm(`Disconnect ${label}? Northlight will stop new work for this integration and remove its encrypted credentials after the provider confirms revocation.`))return;try{const d=await api(`/api/integrations/${provider}/disconnect`,{method:'POST'});toast(`${label} disconnected`,d.message||'Provider access was revoked.');await bootstrap();renderPage()}catch(e){toast(`Could not disconnect ${label}`,e.message)}}
