(async function init(){try{const d=await api('/api/auth/session');state.session=d.session;if(state.session&&state.session.mustChangePassword!==true){await bootstrap();const requested=requestedView();if(requested&&navFor(state.session.role).includes(requested))state.view=requested}}catch{}render()})();
